Japanese:
{
"situation": "Ordering food at a ramen restaurant",
"phrases": [
{
"english": "Excuse me! (To call the staff)",
"translation": "すみません",
"romanization": "sumimasen",
"pronunciation": "soo-mee-mah-SEN",
"note": "Call this out loudly to get the server's attention in a busy shop."
},
{
"english": "One ramen, please.",
"translation": "ラーメンを一つお願いします",
"romanization": "rāmen o hitotsu onegaishimasu",
"pronunciation": "RAH-men oh hee-TOH-tsoo oh-neh-guy-shee-mah-soo",
"note": "Replace 'hitotsu' with 'futatsu' for two orders."
},
{
"english": "What do you recommend?",
"translation": "おすすめは何ですか？",
"romanization": "osusume wa nan desu ka?",
"pronunciation": "oh-soo-soo-meh wah nahn DES-kah?",
"note": "Great for asking the chef or server for their popular dish."
},
{
"english": "Water, please.",
"translation": "お水をお願いします",
"romanization": "omizu o onegaishimasu",
"pronunciation": "oh-MEE-zoo oh oh-neh-guy-shee-mah-soo",
"note": "Most ramen shops offer self-serve water, but you can ask if needed."
},
{
"english": "Thank you for the meal. (When leaving)",
"translation": "ごちそうさまでした",
"romanization": "gochisōsama deshita",
"pronunciation": "goh-chee-soh-sah-mah DESH-tah",
"note": "Say this to the chef or staff as you exit to show appreciation."
},
{
"english": "I don't understand Japanese.",
"translation": "日本語がわかりません",
"romanization": "nihongo ga wakarimasen",
"pronunciation": "nee-hohn-goh gah wah-kah-ree-MAH-sen",
"note": "Use when staff explain customization options or ticket machine instructions."
}
],
"tips": [
"Many traditional ramen shops use a vending machine (shokukenki) near the entrance where you buy a ticket before sitting down.",
"Slurping your noodles loudly is culturally expected; it cools the hot noodles and shows the chef you are enjoying the food."
]
}

Hindi:
{
"situation": "Bargaining at a street market",
"phrases": [
{
"english": "How much is this?",
"translation": "यह कितने का है?",
"romanization": "Yeh kitne ka hai?",
"pronunciation": "ye-h KIT-nay kaa hai",
"note": "Point to the item while asking to clear any confusion."
},
{
"english": "It is a bit expensive.",
"translation": "यह थोड़ा महंगा है।",
"romanization": "Yeh thoda mehanga hai.",
"pronunciation": "ye-h THO-daa me-h-NGA hai",
"note": "Use this gently before suggesting a lower price."
},
{
"english": "Will you give a discount?",
"translation": "क्या आप थोड़ा कम करेंगे?",
"romanization": "Kya aap thoda kam karenge?",
"pronunciation": "kyaa aap THO-daa kam ka-REN-gay",
"note": "Polite way to ask for a lower price."
},
{
"english": "I will give 200 rupees for this.",
"translation": "मैं इसके दो सौ रुपये दूंगा।",
"romanization": "Main iske do sau rupaye doonga.",
"pronunciation": "main IS-kay do saw roo-pay-ay DOON-gaa",
"note": "Female speakers should say 'doongi' instead of 'doonga'."
},
{
"english": "Okay, pack it please.",
"translation": "ठीक है, इसे पैक कर दीजिए।",
"romanization": "Theek hai, ise pack kar dijiyeya.",
"pronunciation": "THEEK hai, i-say pack kar DEE-ji-yay",
"note": "Use when you agree on the final negotiated price."
},
{
"english": "I didn't understand, please say it again.",
"translation": "मैं समझा नहीं, कृपया फिर से कहिए।",
"romanization": "Main samjha nahi, kripya phir se kahiye.",
"pronunciation": "main SAM-jhaa na-hee, KRIP-yaa phir say KA-hi-yay",
"note": "Female speakers should say 'samjhi' instead of 'samjha'."
}
],
"tips": [
"Always start bargaining with a smile; market negotiations in India are meant to be friendly conversations.",
"Carrying small cash notes (₹50, ₹100) makes transactions smoother when negotiating exact amounts."
]
}
